function identifyQuestionFor(level,questionIndex){const target=IDENTIFY_QUESTION_WORDS[((level-1)*10+questionIndex)%IDENTIFY_QUESTION_WORDS.length],distractors=[],usedIcons=new Set([target.icon]);for(const entry of IDENTIFY_WORDS.filter(candidate=>candidate.word!==target.word).sort(()=>Math.random()-.5)){if(usedIcons.has(entry.icon))continue;distractors.push(entry);usedIcons.add(entry.icon);if(distractors.length===3)break}return{target,options:[...distractors,target].sort(()=>Math.random()-.5)}}
function startEnglishIdentifyLevel(level){if(level>identifyUnlockedLevel)return;stopSpeech();identifyLevel=level;identifyQuestionIndex=0;identifyLevelMessage="";hideScreens();$("english-identify-quiz").hidden=false;renderEnglishIdentifyQuestion()}
function renderEnglishIdentifyQuestion(){identifyAnswered=false;identifyCurrentQuestion=identifyQuestionFor(identifyLevel,identifyQuestionIndex);$("english-identify-counter").textContent=`Level ${identifyLevel} · Question ${identifyQuestionIndex+1} of 10`;$("english-identify-question").textContent=`Identify the ${identifyCurrentQuestion.target.word} based on the picture.`;$("english-identify-feedback").textContent="Choose the correct picture!";$("english-identify-next").disabled=true;$("english-identify-next").textContent=identifyQuestionIndex===9?"Finish level ✓":"Next question ➜";const options=$("english-identify-options");options.innerHTML="";identifyCurrentQuestion.options.forEach(option=>{const button=document.createElement("button");button.type="button";button.className="english-identify-option";button.setAttribute("aria-label",`Picture option: ${option.word}`);button.innerHTML=`<span aria-hidden="true">${option.icon}</span>`;button.onclick=()=>chooseEnglishIdentifyOption(button,option);options.appendChild(button)});say([`Identify the ${identifyCurrentQuestion.target.word} based on the picture.`])}
function chooseEnglishIdentifyOption(button,option){if(identifyAnswered||!identifyCurrentQuestion)return;$("english-identify-options").querySelectorAll("button").forEach(optionButton=>optionButton.classList.remove("is-wrong"));if(option.word!==identifyCurrentQuestion.target.word){button.classList.add("is-wrong");$("english-identify-feedback").textContent="Not that picture. Try again!";say(["Not that picture. Try again."]);return}identifyAnswered=true;button.classList.add("is-correct");$("english-identify-options").querySelectorAll("button").forEach(optionButton=>{optionButton.classList.remove("is-wrong");optionButton.disabled=true});$("english-identify-feedback").textContent=`That's right! ${identifyCurrentQuestion.target.word}!`; $("english-identify-next").disabled=false;say([`That's right! ${identifyCurrentQuestion.target.word}!`])}
function advanceEnglishIdentify(){if(!identifyAnswered)return;stopSpeech();if(identifyQuestionIndex<9){identifyQuestionIndex++;renderEnglishIdentifyQuestion();return}if(identifyLevel===identifyUnlockedLevel){identifyUnlockedLevel++;saveIdentifyProgress()}identifyLevelMessage=`Great job! Level ${identifyLevel} complete. Level ${identifyLevel+1} is unlocked!`;identifyLevelPage=Math.floor((identifyLevel-1)/10);hideScreens();$("english-identify-levels").hidden=false;renderEnglishIdentifyLevels();say([identifyLevelMessage])}
