const CHILDREN_STORIES=[
 {id:"mango-feast",genre:"fun",enTitle:"Prince Arin’s Mango Feast",teTitle:"అరిన్ రాకుమారుడి మామిడి విందు",en:["Prince Arin found a basket of golden mangoes in the palace garden. He wanted the biggest one all for himself.","Then he heard the palace cooks. The village children had come to visit, but there was not enough fruit for everyone.","Arin cut the mangoes into little pieces and invited every child to share. The king joined them, and juice tickled his royal moustache!","Everyone laughed together. Arin discovered that a shared treat can taste sweeter than the biggest mango eaten alone."],te:["రాజభవనం తోటలో అరిన్ రాకుమారుడికి బంగారు రంగు మామిడిపండ్ల బుట్ట కనిపించింది. అతి పెద్ద పండు తనకే కావాలని అనుకున్నాడు.","అప్పుడే వంటవాళ్లు మాట్లాడుకోవడం అతనికి వినిపించింది. గ్రామంలోని పిల్లలు వచ్చారు, కానీ అందరికీ సరిపడా పండ్లు లేవు.","అరిన్ మామిడిపండ్లను చిన్న ముక్కలుగా కోసి పిల్లలందరినీ పంచుకోమని పిలిచాడు. రాజు కూడా వచ్చాడు. మామిడి రసం ఆయన మీసాలపై పడింది!","అందరూ కలిసి నవ్వుకున్నారు. ఒంటరిగా తినే పెద్ద పండు కంటే పంచుకున్న పండు రుచిగా ఉంటుందని అరిన్ తెలుసుకున్నాడు."]},
 {id:"ticklish-crown",genre:"fun",enTitle:"King Kiran’s Ticklish Crown",teTitle:"కిరణ్ రాజు కిరీటంలోని చక్కిలిగింతలు",en:["King Kiran had a shiny crown that wobbled whenever he giggled. One morning, it began to wiggle all by itself!","The young prince searched beneath the throne, behind the curtains, and inside the crown’s soft lining.","A tiny feather was tucked inside. The prince brushed it away, and the king burst into happy laughter instead of a royal speech.","The king thanked his curious helper and declared a day of jokes, stories, and laughter for the whole castle."],te:["కిరణ్ రాజు దగ్గర మెరిసే కిరీటం ఉండేది. ఆయన నవ్వితే అది కదిలేది. ఒక ఉదయం రాజు నవ్వకుండానే కిరీటం కదలసాగింది!","యువరాజు సింహాసనం కింద, తెరల వెనుక, కిరీటం లోపల వెతికాడు.","కిరీటం మెత్తని లోపలి భాగంలో ఒక చిన్న ఈక కనిపించింది. యువరాజు దాన్ని తీసేశాడు. రాజు ప్రసంగానికి బదులు గట్టిగా నవ్వారు!","రాజు తన ఆసక్తిగల సహాయకుడికి ధన్యవాదాలు చెప్పారు. కోటంతా కథలు, జోకులు, నవ్వులతో నిండిన రోజును ప్రకటించారు."]},
 {id:"moon-map",genre:"adventure",enTitle:"Princess Mira and the Moonlit Map",teTitle:"వెన్నెల పటంతో యువరాణి మీరా",en:["Princess Mira found a silver map that sparkled only when moonlight touched it. A dotted path led from the palace garden to the river.","She packed a lantern, warm bread, and a compass. Her small brother came too, carrying the map carefully with both hands.","They followed the shining dots through a safe forest path until they found a lost baby owl beside a quiet stream.","Together, they guided the owl home to its nest. Mira learned that a brave journey is even better when you help someone along the way."],te:["చంద్రకాంతి పడినప్పుడే మెరిసే వెండి పటం యువరాణి మీరాకు దొరికింది. చుక్కల దారి రాజభవనపు తోట నుంచి నది వరకు చూపించింది.","ఆమె దీపం, వెచ్చని రొట్టె, దిక్సూచి తీసుకుంది. తమ్ముడు కూడా పటాన్ని జాగ్రత్తగా పట్టుకుని వెంట వచ్చాడు.","సురక్షితమైన అడవి దారి వెంట మెరిసే చుక్కలను అనుసరిస్తూ వెళ్లారు. నిశ్శబ్దమైన వాగు దగ్గర దారి తప్పిన చిన్న గుడ్లగూబ కనిపించింది.","వారిద్దరూ గుడ్లగూబను దాని గూటికి చేర్చారు. ఎవరికైనా సాయం చేస్తే సాహస ప్రయాణం మరింత బాగుంటుందని మీరా తెలుసుకుంది."]},
 {id:"river-of-stars",genre:"adventure",enTitle:"The Little Prince and the River of Stars",teTitle:"చుక్కల నది దగ్గర చిన్న రాకుమారుడు",en:["One evening, a little prince saw a ribbon of light winding through the hills. “The stars have fallen into a river!” he cried.","He followed the glow with his pony and a kind palace gardener. The shining ribbon was a trail of tiny fireflies above a stream.","They crossed a wooden bridge and found a lantern tangled in the reeds. Its warm light had brought the fireflies close.","The prince freed the lantern and left it safely on the bank. He returned home smiling, with a wonderful story for the king."],te:["ఒక సాయంత్రం చిన్న రాకుమారుడు కొండల మధ్య వెలుగుల రిబ్బన్‌లా కనిపించే దారిని చూశాడు. “చుక్కలు నదిలో పడిపోయాయి!” అని ఆశ్చర్యపోయాడు.","తన గుర్రం, రాజభవనపు తోటమాలితో కలిసి ఆ వెలుగు వెంట వెళ్లాడు. అది వాగు పైన ఎగురుతున్న చిన్న మిణుగురు పురుగుల వరుస.","చెక్క వంతెన దాటి వెళ్లగా, రెల్లులో చిక్కుకున్న ఒక దీపం కనిపించింది. దాని వెచ్చని వెలుగుతో మిణుగురు పురుగులు అక్కడికి చేరాయి.","రాకుమారుడు దీపాన్ని విడిపించి ఒడ్డున సురక్షితంగా ఉంచాడు. రాజుకు చెప్పడానికి అద్భుతమైన కథతో నవ్వుతూ ఇంటికి తిరిగొచ్చాడు."]},
 {id:"sky-painter",genre:"wonder",enTitle:"King Vihan’s Sky of Seven Colors",teTitle:"విహాన్ రాజు ఏడు రంగుల ఆకాశం",en:["King Vihan wished to brighten the gray sky above his castle. The young prince brought seven bright paints and a very long brush.","They climbed a hill and painted careful stripes: red, orange, yellow, green, blue, indigo, and violet.","A little rain fell, and the colors curved across the clouds like a giant rainbow bridge. People in the kingdom came outside to admire it.","The king smiled. The prince said the sky had made the picture with them. They shared the paints so every child could make a colorful picture too."],te:["కోట పైన ఉన్న మబ్బుల ఆకాశాన్ని రంగులమయం చేయాలని విహాన్ రాజు కోరుకున్నాడు. యువరాజు ఏడు రంగులు, పొడవైన కుంచె తీసుకొచ్చాడు.","వాళ్లు ఒక కొండపైకి వెళ్లి ఎరుపు, నారింజ, పసుపు, ఆకుపచ్చ, నీలం, నీలిమందు, ఊదా రంగులతో గీతలు గీశారు.","చినుకులు పడగానే ఆ రంగులు మేఘాల మీద పెద్ద ఇంద్రధనుస్సు వంతెనలా వంగాయి. రాజ్యంలోని ప్రజలందరూ బయటకు వచ్చి చూశారు.","రాజు ఆనందంగా నవ్వాడు. “ఈ చిత్రాన్ని ఆకాశం మనతో కలిసి వేసింది” అన్నాడు యువరాజు. పిల్లలందరికీ రంగులు పంచారు."]},
 {id:"moon-palace",genre:"wonder",enTitle:"The Palace Beneath the Lake",teTitle:"సరస్సు కింద వెలుగుల భవనం",en:["A young prince looked into a clear lake and saw a palace shining beneath the water. Was it a dream, or a hidden world?","The king brought a glass-bottomed boat. They floated slowly above the water, watching silver fish, waving plants, and sunlight dance below.","A school of tiny fish swam together, making a bright shape like a palace gate. The “castle” was a beautiful picture made by nature.","The prince thanked the lake for its wonder. The king promised to keep the water clean so the little fish would always have a lovely home."],te:["ఒక చిన్న రాకుమారుడు స్వచ్ఛమైన సరస్సులోకి చూశాడు. నీటి కింద మెరిసే భవనం కనిపించింది. అది కలనా, రహస్య ప్రపంచమా?","రాజు అద్దపు అడుగున్న పడవ తెప్పించాడు. నీటిపై నెమ్మదిగా తేలుతూ వెండి చేపలు, ఊగే మొక్కలు, నీటిలో నాట్యం చేసే ఎండ వెలుగును చూశారు.","చిన్న చేపల గుంపు కలిసి ఈదుతూ భవన ద్వారం లాంటి వెలుగుల ఆకారాన్ని చేసింది. ఆ “కోట” ప్రకృతి సృష్టించిన అందమైన చిత్రం.","సరస్సు చూపిన అద్భుతానికి రాకుమారుడు కృతజ్ఞతలు చెప్పాడు. చిన్న చేపలకు మంచి ఇల్లు ఉండేలా నీటిని శుభ్రంగా ఉంచుతానని రాజు మాట ఇచ్చాడు."]},
 {id:"ramas-bridge",genre:"mythology",enTitle:"Rama and the Bridge of Courage",teTitle:"ధైర్యపు వంతెన నిర్మించిన రాముడు",en:["In the Ramayana, Prince Rama needed to cross the sea with his friends to help Sita. The ocean seemed very wide.","The vanara friends worked together. They carried stones and placed them carefully, one beside another, building a path across the water.","Some friends were strong, and some were small. Every careful helping hand mattered as they worked together with courage.","Their teamwork made the journey possible. The story reminds us that brave hearts and helping one another can overcome a very big challenge."],te:["రామాయణంలో, సీతకు సాయం చేయడానికి రాముడు తన మిత్రులతో సముద్రం దాటాల్సి వచ్చింది. సముద్రం ఎంతో విశాలంగా కనిపించింది.","వానర మిత్రులంతా కలిసి పని చేశారు. రాళ్లను మోసుకొచ్చి జాగ్రత్తగా ఒకదాని పక్కన మరొకటి పెట్టి నీటిపై దారి నిర్మించారు.","కొంతమంది బలవంతులు, మరికొందరు చిన్నవారు. ధైర్యంగా కలిసి పనిచేస్తూ ప్రతి ఒక్కరూ సాయం చేశారు.","వారి ఐకమత్యం ప్రయాణాన్ని సాధ్యం చేసింది. ధైర్యం, పరస్పర సహాయం ఉంటే పెద్ద కష్టాన్నైనా ఎదుర్కోవచ్చని ఈ కథ చెబుతుంది."]},
 {id:"arjunas-aim",genre:"mythology",enTitle:"Arjuna’s Unwavering Aim",teTitle:"అర్జునుడి ఏకాగ్రత",en:["In the Mahabharata, teacher Dronacharya asked his students to look at a bird on a distant tree. “What do you see?” he asked.","Some students noticed the branches, the leaves, and the sky. Arjuna looked carefully and said he could see only the bird’s eye.","His calm attention helped him aim his arrow with great care. Dronacharya praised the way he stayed focused on his task.","Arjuna’s lesson is useful for all of us: take a quiet breath, pay attention, and give one important job your best effort."],te:["మహాభారతంలో గురువు ద్రోణాచార్యుడు తన శిష్యులను దూరంగా చెట్టుపై ఉన్న పక్షిని చూడమన్నాడు. “మీకు ఏమి కనిపిస్తోంది?” అని అడిగాడు.","కొంతమంది కొమ్మలు, ఆకులు, ఆకాశం చూశారు. అర్జునుడు జాగ్రత్తగా చూసి, తనకు పక్షి కన్ను మాత్రమే కనిపిస్తోందని చెప్పాడు.","అతని ప్రశాంతమైన ఏకాగ్రత వల్ల బాణాన్ని ఎంతో జాగ్రత్తగా గురి పెట్టాడు. పనిపై దృష్టి నిలిపిన విధానాన్ని ద్రోణాచార్యుడు మెచ్చుకున్నాడు.","అర్జునుడి కథ మనకూ ఉపయోగపడుతుంది: నెమ్మదిగా శ్వాస తీసుకుని, శ్రద్ధగా గమనించి, ఒక పనిని బాగా చేద్దాం."]},
 {id:"friendly-ghost",genre:"horror",enTitle:"Prince Nalin and the Friendly Ghost",teTitle:"నలిన్ రాకుమారుడు, స్నేహపూర్వక దయ్యం",en:["At bedtime, Prince Nalin heard a soft “whooo” from the old clock tower. He felt a little nervous, so the king came with him to investigate.","Inside, a tiny white ghost was shivering beside an open window. The night breeze had made the old clock chime.","Nalin gently closed the window. The friendly ghost thanked him and showed them how to wind the clock so it would chime at morning instead.","They all smiled, and the ghost became the castle’s gentle timekeeper. Nalin learned that a strange sound is easier to understand when we look calmly and ask for help."],te:["నిద్రపోయే వేళ పాత గడియారపు గోపురం నుంచి “ఊఊ” అనే మృదువైన శబ్దం వినిపించింది. నలిన్‌కు కొంచెం భయం వేసింది. రాజు అతనితో కలిసి చూడటానికి వచ్చాడు.","లోపల తెరిచి ఉన్న కిటికీ పక్కన చిన్న తెల్లటి దయ్యం వణుకుతూ కనిపించింది. రాత్రి గాలి పాత గడియారాన్ని మోగిస్తోంది.","నలిన్ మెల్లగా కిటికీ మూశాడు. దయ్యం ధన్యవాదాలు చెప్పి, ఉదయం గంట మోగేలా గడియారాన్ని ఎలా తిప్పాలో చూపించింది.","అందరూ నవ్వుకున్నారు. దయ్యం కోటకు మంచి గడియార సంరక్షకుడైంది. వింత శబ్దం వినిపిస్తే ప్రశాంతంగా చూసి, పెద్దవారిని సాయం అడగాలని నలిన్ తెలుసుకున్నాడు."]},
 {id:"whispering-tower",genre:"horror",enTitle:"The King’s Whispering Tower",teTitle:"రాజు గోపురంలో రహస్య గుసగుస",en:["The young king heard a whisper in the highest tower: “Whooo left the window open?” He invited the little prince to help solve the mystery.","They climbed the round stairs with a lantern. The whisper came again whenever the wind slipped through a crack in the window.","The prince found a loose wooden shutter tapping softly against the wall. Together, they fastened it securely with a ribbon.","The whispering stopped, and an owl gave one friendly hoot from the roof. The king laughed, thanked his clever helper, and everyone slept peacefully."],te:["ఎత్తైన గోపురంలో “కిటికీ ఎవరు తెరిచి ఉంచారు?” అనే గుసగుస యువరాజుకు వినిపించింది. రహస్యం తెలుసుకోవడానికి చిన్న రాకుమారుడిని రాజు పిలిచాడు.","దీపం పట్టుకుని గుండ్రని మెట్లెక్కారు. కిటికీలోని చిన్న సందులోంచి గాలి వీచినప్పుడల్లా మళ్లీ ఆ గుసగుస వినిపించింది.","గోడకు మెల్లగా తగులుతున్న వదులైన చెక్క తలుపును రాకుమారుడు కనుగొన్నాడు. ఇద్దరూ కలిసి దాన్ని రిబ్బన్‌తో గట్టిగా కట్టారు.","గుసగుస ఆగిపోయింది. పైకప్పు మీద గుడ్లగూబ స్నేహంగా ఒకసారి అరచింది. రాజు తెలివైన సహాయకుడికి కృతజ్ఞతలు చెప్పాడు. అందరూ ప్రశాంతంగా నిద్రపోయారు."]},
 {id:"lantern-lunch",genre:"fun",enTitle:"The Lantern That Loved Lunch",teTitle:"భోజనాన్ని ఇష్టపడిన దీపం",en:["At the palace picnic, Princess Tara brought a lantern that glowed whenever someone told a joke.","The king told a silly story about a sleepy goat. The lantern flickered, but it did not shine brightly.","A shy gardener shared a tiny joke about a carrot wearing a crown. The lantern glowed like a little sun, and everyone laughed.","Tara invited the gardener to sit with them. The picnic became brighter when everyone had a chance to join in."],te:["రాజభవనం తోటలో విందుకు తార యువరాణి ఒక దీపం తెచ్చింది. ఎవరైనా జోక్ చెబితే అది వెలిగేది.","నిద్రపోయే మేక గురించి రాజు ఒక సరదా కథ చెప్పాడు. దీపం కొంచెం మెరిసింది కానీ పూర్తిగా వెలగలేదు.","సిగ్గుపడే తోటమాలి కిరీటం పెట్టుకున్న క్యారెట్ గురించి చిన్న జోక్ చెప్పాడు. దీపం చిన్న సూర్యుడిలా వెలిగింది. అందరూ నవ్వారు.","తోటమాలిని కూడా తమతో కూర్చోమని తార ఆహ్వానించింది. అందరికీ మాట్లాడే అవకాశం దొరకడంతో విందు మరింత ఆనందంగా మారింది."]},
 {id:"cloud-boat",genre:"adventure",enTitle:"The Cloud Boat Rescue",teTitle:"మేఘపు పడవతో రక్షణ",en:["Prince Dev spotted a tiny cloud shaped like a boat drifting above the hills. A little bird was perched on it, chirping for help.","He asked the palace kite-maker to help. Together they flew a gentle kite close to the cloud boat.","The bird hopped onto the kite string and rode safely down to a soft patch of grass.","Dev cheered for his careful helper. The best adventures use patience and teamwork, not rushing."],te:["కొండల పైన పడవ ఆకారంలో తేలుతున్న చిన్న మేఘాన్ని దేవ్ రాకుమారుడు చూశాడు. దానిపై ఉన్న పక్షిపిల్ల సాయం కోసం కిచకిచలాడుతోంది.","రాజభవనపు గాలిపటాలు చేసే వ్యక్తిని దేవ్ పిలిచాడు. ఇద్దరూ మేఘపు పడవ దగ్గరకు మెల్లగా గాలిపటాన్ని ఎగరవేశారు.","పక్షిపిల్ల గాలిపటం దారంపైకి దూకి, సురక్షితంగా మెత్తని గడ్డి మీదకు చేరుకుంది.","దేవ్ తన సహాయకుడిని అభినందించాడు. తొందరపడకుండా, ఓపికగా కలిసి పనిచేస్తేనే మంచి సాహసాలు సాధ్యమవుతాయి."]},
 {id:"seed-of-sunlight",genre:"wonder",enTitle:"The Seed of Sunlight",teTitle:"సూర్యకాంతి విత్తనం",en:["A little prince found a golden seed that glimmered only when someone smiled at it.","He planted it in the castle garden and watered it with care. Each day, a tiny green shoot reached toward the sun.","The prince invited the children of the village to tend the garden with him. Soon, bright flowers opened in every color.","The garden grew because many caring hands looked after it. The king shared the flowers with everyone in the village."],te:["ఎవరైనా చిరునవ్వు నవ్వినప్పుడే మెరిసే బంగారు విత్తనం ఒక చిన్న రాకుమారుడికి దొరికింది.","దాన్ని రాజభవనం తోటలో నాటి, జాగ్రత్తగా నీళ్లు పోశాడు. ప్రతి రోజూ చిన్న మొలక సూర్యుని వైపు పెరిగింది.","గ్రామంలోని పిల్లలను తోటను చూసుకోవడానికి రమ్మని రాకుమారుడు పిలిచాడు. త్వరలోనే ఎన్నో రంగుల పూలు వికసించాయి.","చాలామంది ప్రేమగా చూసుకోవడంతో తోట పెరిగింది. రాజు ఆ పూలను గ్రామస్థులందరితో పంచుకున్నాడు."]},
 {id:"ganeshas-kind-plan",genre:"mythology",enTitle:"Ganesha and the Kind Plan",teTitle:"వినాయకుడి మంచి ఆలోచన",en:["One day, Ganesha and his friends found that the garden path was too muddy for the little animals to cross.","Ganesha listened to each friend’s idea before choosing a safe path around the puddle.","Together they placed flat stones along the new path, helping even the tiniest mouse walk across.","By listening and working together, the friends made a way for everyone. A thoughtful plan can help the whole community."],te:["ఒక రోజు తోటలోని బురద దారిని చిన్న జంతువులు దాటలేకపోతున్నాయని వినాయకుడు, అతని మిత్రులు గమనించారు.","బురద గుంట చుట్టూ సురక్షితమైన దారి ఎంచుకునే ముందు వినాయకుడు ప్రతి మిత్రుడి మాట విన్నాడు.","కలిసి చదునైన రాళ్లను కొత్త దారిలో పెట్టారు. చిన్న ఎలుక కూడా సులభంగా నడిచి వెళ్లింది.","అందరి మాట విని కలిసి పనిచేయడంతో అందరికీ దారి ఏర్పడింది. ఆలోచించి చేసే పని అందరికీ మేలు చేస్తుంది."]},
 {id:"star-in-the-stairwell",genre:"horror",enTitle:"The Star in the Stairwell",teTitle:"మెట్ల దగ్గర చిన్న నక్షత్రం",en:["A little prince saw a blue light moving in the castle stairwell after sunset. He felt unsure and called his aunt to come with him.","They followed the light together and found a firefly trapped inside an empty glass jar.","The prince opened the jar outdoors, and the firefly blinked happily among the garden flowers.","He learned that asking a trusted grown-up to help can turn a worry into a gentle discovery."],te:["సూర్యాస్తమయం తర్వాత కోట మెట్ల దగ్గర నీలిరంగు వెలుగు కదలడం చిన్న రాకుమారుడు చూశాడు. సందేహంగా అనిపించడంతో అత్తను తోడుగా రమ్మన్నాడు.","ఇద్దరూ కలిసి వెలుగు వెంట వెళ్లి ఖాళీ గాజు సీసాలో చిక్కుకున్న మిణుగురు పురుగును కనుగొన్నారు.","రాకుమారుడు బయట సీసా తెరవగానే, మిణుగురు పురుగు తోట పూల మధ్య ఆనందంగా మెరిసింది.","నమ్మకమైన పెద్దవారి సాయం అడిగితే భయం మంచి అనుభవంగా మారుతుందని అతను తెలుసుకున్నాడు."]}
];
const STORY_MORALS={
 "mango-feast":{en:"Sharing makes happiness grow.",te:"పంచుకుంటే ఆనందం పెరుగుతుంది."},
 "ticklish-crown":{en:"Curiosity and kindness can brighten everyone’s day.",te:"ఆసక్తి, మంచితనం అందరి రోజును ఆనందంగా మారుస్తాయి."},
 "moon-map":{en:"A brave journey is better when we help others.",te:"ఇతరులకు సాయం చేస్తే సాహస ప్రయాణం మరింత బాగుంటుంది."},
 "river-of-stars":{en:"Look closely and care for the little things around you.",te:"చుట్టూ ఉన్న చిన్న విషయాలను శ్రద్ధగా గమనించి, ప్రేమగా చూసుకోండి."},
 "sky-painter":{en:"Creativity is even more joyful when we share it.",te:"మన సృజనాత్మకతను పంచుకుంటే ఆనందం మరింత పెరుగుతుంది."},
 "moon-palace":{en:"Protect nature and the homes of every living creature.",te:"ప్రకృతిని, జీవుల నివాసాలను కాపాడాలి."},
 "ramas-bridge":{en:"Courage and teamwork help us face big challenges.",te:"ధైర్యం, ఐకమత్యం పెద్ద కష్టాలను ఎదుర్కోవడంలో సాయం చేస్తాయి."},
 "arjunas-aim":{en:"Calm focus helps us do our best.",te:"ప్రశాంతమైన ఏకాగ్రత మన పనిని బాగా చేయడంలో సాయం చేస్తుంది."},
 "friendly-ghost":{en:"Stay calm, investigate safely, and ask a trusted grown-up for help.",te:"ప్రశాంతంగా ఉండి, సురక్షితంగా పరిశీలించి, నమ్మకమైన పెద్దవారి సాయం అడగండి."},
 "whispering-tower":{en:"Careful observation can solve a mystery.",te:"జాగ్రత్తగా గమనిస్తే రహస్యాన్ని తెలుసుకోవచ్చు."},
 "lantern-lunch":{en:"Everyone deserves a chance to join in.",te:"అందరికీ పాల్గొనే అవకాశం ఇవ్వాలి."},
 "cloud-boat":{en:"Patience and teamwork make a safer adventure.",te:"ఓపిక, ఐకమత్యం సురక్షితమైన సాహసానికి తోడ్పడతాయి."},
 "seed-of-sunlight":{en:"When we care for something together, everyone can enjoy it.",te:"కలిసి ప్రేమగా చూసుకుంటే అందరూ దాని ఆనందాన్ని పొందగలరు."},
 "ganeshas-kind-plan":{en:"Listen to others and find a way that helps everyone.",te:"ఇతరుల మాట విని అందరికీ మేలు చేసే దారిని కనుక్కోండి."},
 "star-in-the-stairwell":{en:"When something worries you, ask a trusted grown-up for help.",te:"ఏదైనా ఆందోళన కలిగిస్తే నమ్మకమైన పెద్దవారి సాయం అడగండి."}
};
let currentStoryGenre="",currentStoryId="";
let englishDeityLetter="";
function showEnglishAlphabets(){stopSpeech();englishLetter="";hideScreens();$("english-alphabets").hidden=false;$("english-alphabet-display").innerHTML='<div class="alphabet-display-placeholder"><span aria-hidden="true">🌟</span><strong>Choose a letter!</strong></div>';const grid=$("english-alphabets-grid");grid.innerHTML=[..."ABCDEFGHIJKLMNOPQRSTUVWXYZ"].map(character=>`<button type="button" aria-label="Show letter ${character}" aria-pressed="false">${character}</button>`).join("");grid.querySelectorAll("button").forEach(button=>button.onclick=()=>showEnglishAlphabet(button.textContent));say(["Tap a letter to learn the alphabet."])}
let englishEpicWarriorLetter="";
function showEnglishEpicWarriors(){stopSpeech();hideScreens();$("english-epic-warriors").hidden=false;const grid=$("english-warrior-grid");grid.innerHTML=[..."ABCDEFGHIJKLMNOPQRSTUVWXYZ"].map(character=>{const warrior=EPIC_WARRIORS[character];const label=warrior?`${character} is for ${warrior.name}`:`${character}, no warrior listed`;return `<button type="button" class="english-warrior-letter-button${warrior?"":" english-warrior-unavailable"}" data-warrior-letter="${character}" aria-haspopup="dialog" aria-label="${label}"><strong>${character}</strong><span>${warrior?warrior.name:"No warrior listed"}</span></button>`}).join("");grid.querySelectorAll("[data-warrior-letter]").forEach(button=>button.onclick=()=>showEnglishEpicWarrior(button.dataset.warriorLetter));say(["Choose a letter to learn about a warrior from the Ramayana or Mahabharata."])}
function showEnglishEpicWarrior(character){englishEpicWarriorLetter=character;const warrior=EPIC_WARRIORS[character],dialog=$("english-warrior-dialog"),image=$("english-warrior-dialog-image"),imagePlaceholder=$("english-warrior-dialog-image-placeholder");$("english-warrior-dialog-letter").textContent=character;if(warrior){$("english-warrior-dialog-title").textContent=`${character} is for ${warrior.name}`;$("english-warrior-dialog-description").textContent=warrior.description;if(warrior.image){const picture=EPIC_WARRIOR_IMAGES[warrior.image];image.src=picture.src;image.alt=picture.alt;image.hidden=false;imagePlaceholder.hidden=true}else{image.removeAttribute("src");image.alt="";image.hidden=true;imagePlaceholder.textContent="Picture not available";imagePlaceholder.hidden=false}}else{$("english-warrior-dialog-title").textContent=`${character}: no warrior listed`;$("english-warrior-dialog-description").textContent=`No commonly recognized warrior from the Ramayana or Mahabharata is listed for ${character}. Choose another letter to learn a warrior's name.`;image.removeAttribute("src");image.alt="";image.hidden=true;imagePlaceholder.textContent="No name for this letter";imagePlaceholder.hidden=false}if(!dialog.open)dialog.showModal();sayEnglishEpicWarriorIntroduction()}
function sayEnglishEpicWarriorIntroduction(){const warrior=EPIC_WARRIORS[englishEpicWarriorLetter];say(warrior?[`${englishEpicWarriorLetter} is for ${warrior.name}.`,warrior.description]:[`No commonly recognized warrior from the Ramayana or Mahabharata is listed for ${englishEpicWarriorLetter}. Choose another letter to learn a warrior's name.`])}
function closeEnglishEpicWarrior(){stopSpeech();const dialog=$("english-warrior-dialog");if(dialog.open)dialog.close()}
function showEnglishDeityLetters(){stopSpeech();hideScreens();$("english-deity-letters").hidden=false;const grid=$("english-deity-grid");grid.innerHTML=[..."ABCDEFGHIJKLMNOPQRSTUVWXYZ"].map(character=>`<button type="button" aria-label="${character}${INDIAN_DEITY_LETTERS[character]?` for ${INDIAN_DEITY_LETTERS[character].name}`:", no common deity name"}" aria-pressed="false">${character}</button>`).join("");grid.querySelectorAll("button").forEach(button=>button.onclick=()=>showEnglishDeityLetter(button.textContent));showEnglishDeityLetter("A")}
function showEnglishDeityLetter(character){englishDeityLetter=character;const deity=INDIAN_DEITY_LETTERS[character],display=$("english-deity-display");$("english-deity-grid").querySelectorAll("button").forEach(button=>button.setAttribute("aria-pressed",String(button.textContent===character)));if(!deity){const note=`${character} has no widely used English transliteration of an Indian deity name beginning with this letter. Choose another letter to learn a name.`;display.innerHTML=`<article class="english-deity-card-content"><div class="english-deity-letter">${character}</div><div class="english-deity-image-placeholder" aria-hidden="true">📖</div><div class="english-deity-copy"><strong>${character} is an uncommon starting letter</strong><p>${note}</p></div></article>`;say([note]);return}const image=INDIAN_DEITY_IMAGES[deity.image];display.innerHTML=`<article class="english-deity-card-content"><div class="english-deity-letter">${character}</div><img class="english-deity-photo" src="${image.src}" alt="${image.alt}" loading="lazy" decoding="async"><div class="english-deity-copy"><strong>${character} is for ${deity.name}</strong><p>${deity.description}</p></div></article>`;say([`${character} is for ${deity.name}.`,deity.description])}
function sayEnglishDeityLetter(){if(!englishDeityLetter){say(["Choose a letter to learn an Indian deity name."]);return}const deity=INDIAN_DEITY_LETTERS[englishDeityLetter];say(deity?[`${englishDeityLetter} is for ${deity.name}.`,deity.description]:[`${englishDeityLetter} has no widely used English transliteration of an Indian deity name beginning with this letter. Choose another letter to learn a name.`])}
function showEnglishAlphabet(character){englishLetter=character;const[word,icon]=W[character][0],display=$("english-alphabet-display");$("english-alphabets-grid").querySelectorAll("button").forEach(button=>button.setAttribute("aria-pressed",String(button.textContent===character)));display.innerHTML=`<div class="alphabet-display-card"><div class="alphabet-display-letter" aria-label="${character} uppercase, ${character.toLowerCase()} lowercase">${character}<span>${character.toLowerCase()}</span></div><div class="alphabet-display-icon" aria-hidden="true">${icon}</div><div class="alphabet-display-example"><strong>${character} is for ${word}!</strong><span>${word}</span></div></div>`;say([`${character}. ${character} is for ${word}.`])}
function sayEnglishAlphabet(){if(!englishLetter){say(["Tap a letter to learn the alphabet."]);return}const[word]=W[englishLetter][0];say([`${englishLetter}. ${englishLetter} is for ${word}.`])}
function showEnglishLetter(character){englishLetter=character;const words=englishWordsForLetter(character),list=$("english-word-list");$("english-selected-letter").textContent=`${character} words (${words.length})`;list.innerHTML="";$("english-alphabet").querySelectorAll("button").forEach(button=>button.setAttribute("aria-pressed",String(button.textContent===character)));
 if(!words.length){list.innerHTML='<p class="english-no-words">No words in this group yet. Try another letter!</p>';say([character]);return}
 words.forEach(([word,icon])=>{const button=document.createElement("button");button.type="button";button.className="english-word-card";button.setAttribute("aria-label",`Hear ${word}`);button.innerHTML=`<span class="english-word-icon" aria-hidden="true">${icon}</span><span class="english-word-text">${word}</span><span class="english-word-speaker" aria-hidden="true">🔊</span>`;button.onclick=()=>{list.querySelectorAll(".english-word-card").forEach(card=>card.classList.remove("is-selected"));button.classList.add("is-selected");say([word])};list.appendChild(button)});say([character,words[0][0]])}
function showEnglishLesson(type){stopSpeech();englishWordType=type;englishLetter="";hideScreens();$("english-lesson").hidden=false;const labels={two:"2-letter words",three:"3-letter words",multi:"Multi-letter words"};$("english-lesson-title").textContent=labels[type];$("english-lesson-intro").textContent=`Choose a letter to explore ${labels[type].toLowerCase()}. Tap any word to hear it.`;const alphabet=$("english-alphabet");alphabet.innerHTML=[..."ABCDEFGHIJKLMNOPQRSTUVWXYZ"].map(character=>`<button type="button" aria-label="Letter ${character}" aria-pressed="false">${character}</button>`).join("");alphabet.scrollTop=0;alphabet.querySelectorAll("button").forEach(button=>button.onclick=()=>showEnglishLetter(button.textContent));$("english-selected-letter").textContent="Choose a letter";$("english-word-list").innerHTML="";say([labels[type]])}
