const NUMBER_ONES=["","one","two","three","four","five","six","seven","eight","nine"],NUMBER_TEENS=["ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"],NUMBER_TENS=["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"],NUMBER_SCALES=["","thousand","million","billion","trillion","quadrillion","quintillion","sextillion","septillion","octillion","nonillion","decillion","undecillion","duodecillion","tredecillion","quattuordecillion","quindecillion","sexdecillion","septendecillion","octodecillion","novemdecillion","vigintillion"];
function threeDigitName(value){let result="";if(value>=100){result=`${NUMBER_ONES[Math.floor(value/100)]} hundred`;value%=100;if(value)result+=" ";}if(value>=20){result+=NUMBER_TENS[Math.floor(value/10)];if(value%10)result+=`-${NUMBER_ONES[value%10]}`}else if(value>=10)result+=NUMBER_TEENS[value-10];else if(value)result+=NUMBER_ONES[value];return result}
function numberName(value){let number=BigInt(value);if(number===0n)return"zero";const parts=[];let scale=0;while(number>0n){const group=Number(number%1000n);if(group){const scaleName=scale<NUMBER_SCALES.length?NUMBER_SCALES[scale]:`10 to the power ${scale*3}`;parts.unshift(`${threeDigitName(group)}${scaleName?` ${scaleName}`:""}`)}number/=1000n;scale++}return parts.join(" ")}
function romanUnderFourThousand(number){const values=[[1000,"M"],[900,"CM"],[500,"D"],[400,"CD"],[100,"C"],[90,"XC"],[50,"L"],[40,"XL"],[10,"X"],[9,"IX"],[5,"V"],[4,"IV"],[1,"I"]];let result="";for(const [value,symbol] of values){while(number>=value){result+=symbol;number-=value}}return result}
function romanNumber(value){const number=BigInt(value);if(number<4000n)return romanUnderFourThousand(Number(number));const thousands=number/1000n,remainder=Number(number%1000n),higher=romanNumber(thousands).replace(/([IVXLCDM])/g,"$1\u0305");return higher+romanUnderFourThousand(remainder)}
function clearCountingDisplay(){const display=$("math-counting-display");display.classList.remove("has-number","is-roman","is-number");display.innerHTML='<span class="math-counting-placeholder" aria-hidden="true">🌟</span><strong>Pick a number!</strong>'}
function showCountingScreen(kind){stopSpeech();countingKind=kind;countingPage=0n;countingSelection=null;hideScreens();$("math-counting-screen").hidden=false;const roman=kind==="roman";$("math-counting-title").textContent=roman?"Roman Numbers":"Numbers";$("math-counting-intro").textContent=roman?"Choose a number to see its Roman numeral and hear its name!":"Choose a number to see it, hear it, and count it!";$("math-counting-keyboard").setAttribute("aria-label",roman?"Choose a number to see its Roman numeral":"Choose a number");clearCountingDisplay();renderCountingPage();say([$("math-counting-intro").textContent])}
function renderCountingPage(){const start=countingPage*15n+1n,end=start+14n,keyboard=$("math-counting-keyboard");$("math-counting-page-label").textContent=`Numbers ${start}–${end}`;$("math-counting-previous").disabled=countingPage===0n;keyboard.innerHTML=Array.from({length:15},(_,index)=>{const value=start+BigInt(index);return `<button class="math-counting-key" type="button" data-counting-number="${value}" aria-label="${countingKind==="roman"?`Number ${value}, ${romanNumber(value)}`:`Number ${value}, ${numberName(value)}`}" aria-pressed="${countingSelection===value?"true":"false"}">${value}</button>`}).join("");keyboard.querySelectorAll("[data-counting-number]").forEach(button=>button.onclick=()=>showCountingNumber(BigInt(button.dataset.countingNumber)));$("math-counting-previous").disabled=countingPage===0n}
function showCountingNumber(value){countingSelection=value;renderCountingPage();const display=$("math-counting-display"),name=numberName(value),roman=countingKind==="roman",count=value<=10n?Number(value):0;display.classList.remove("has-number","is-roman","is-number");display.classList.add("has-number",roman?"is-roman":"is-number");const countVisual=roman?"":count?`<span class="math-counting-icons" aria-label="${count} icons">${Array.from({length:count},()=>'<span aria-hidden="true">⭐</span>').join("")}</span>`:'<span class="math-counting-cap">Count icons are shown for numbers 1–10.</span>';display.innerHTML=`<span class="math-counting-digit">${value}</span>${roman?`<span class="math-counting-roman">${romanNumber(value)}</span>`:`<span class="math-counting-name">${name}</span>`}${countVisual}`;say(roman?[name]:[`${value} ${name}`])}
function hearCountingNumber(){if(countingSelection===null){say([countingKind==="roman"?"Choose a number to hear its name.":"Choose a number to hear it."]);return}const name=numberName(countingSelection);say(countingKind==="roman"?[name]:[`${countingSelection} ${name}`])}
function showMathTopic(event){stopSpeech();mathTopic=event.currentTarget.dataset.mathTopic;showMathMode()}
function mathOperation(){return{Addition:{symbol:"+",verb:"add",explanation:"putting groups together",icon:"➕"},Subtraction:{symbol:"−",verb:"take away",explanation:"taking some away to see what remains",icon:"➖"},Multiplication:{symbol:"×",verb:"groups of",explanation:"counting equal groups",icon:"✖️"},Division:{symbol:"÷",verb:"share",explanation:"sharing equally into groups",icon:"➗"}}[mathTopic]}
function showMathMode(){cancelAdditionAnimation();hideScreens();$("math-mode-screen").hidden=false;const operation=mathOperation();$("math-mode-icon").textContent=operation.icon;$("math-mode-title").textContent=`${mathTopic}: choose how to learn`;$("math-mode-intro").textContent=`Learn ${mathTopic.toLowerCase()} with pictures, practice with questions, or solve story questions level by level.`;say([`${mathTopic}. Choose how to learn.`,"Learning, Questionaries, or Story Questions."])}
function startMathLearning(){stopSpeech();mathFlow="learning";additionLevel=1;additionFirst=mathTopic==="Subtraction"?2:mathTopic==="Division"?2:1;additionSecond=1;showAdditionLesson()}
